const raw = String($json.body?.url ?? '').trim();
if (!raw) throw new Error('Falta la URL');
const withProto = raw.includes('://') ? raw : `https://${raw}`;
const url = new URL(withProto);
if (!['http:', 'https:'].includes(url.protocol) || !url.hostname.includes('.') || url.hostname === 'localhost' || /^(\d{1,3}\.){3}\d{1,3}$/.test(url.hostname)) {
  throw new Error('URL no válida');
}
return [{ json: { url: url.toString(), hostname: url.hostname.replace(/^www\./, '') } }];

const html = String($input.first().json.data ?? $input.first().json.body ?? '');
const hostname = $('Preparar URL').first().json.hostname;
const base = $('Preparar URL').first().json.url;
const meta = [];
const title = html.match(/<title[^>]*>([\s\S]*?)<\/title>/i)?.[1]?.trim();
const desc = html.match(/<meta[^>]+name=["']description["'][^>]+content=["']([^"']*)["']/i)?.[1];
if (title) meta.push(`Título: ${title}`);
if (desc) meta.push(`Descripción: ${desc}`);
const text = html
  .replace(/<script[\s\S]*?<\/script>/gi, ' ')
  .replace(/<style[\s\S]*?<\/style>/gi, ' ')
  .replace(/<\/(p|div|li|h[1-6]|tr|section|article|br)>/gi, '\n')
  .replace(/<[^>]+>/g, ' ')
  .replace(/&nbsp;/g, ' ').replace(/&amp;/g, '&').replace(/&[a-z]+;/gi, ' ')
  .replace(/[ \t]+/g, ' ').replace(/\n\s*\n+/g, '\n').trim();
let favicon = `https://www.google.com/s2/favicons?domain=${hostname}&sz=128`;
const icon = html.match(/<link[^>]+rel=["'][^"']*icon[^"']*["'][^>]*href=["']([^"']+)["']/i)?.[1] || html.match(/<link[^>]+href=["']([^"']+)["'][^>]*rel=["'][^"']*icon[^"']*["']/i)?.[1];
if (icon && !icon.startsWith('data:')) { try { favicon = new URL(icon, base).toString(); } catch (e) {} }
if (text.length < 80 && meta.length === 0) throw new Error('La web no tiene texto legible');
return [{ json: { hostname, favicon, siteText: `${meta.join('\n')}\n\n${text}`.trim().slice(0, 14000) } }];

const res = $input.first().json;
const content = res.choices?.[0]?.message?.content;
if (!content) throw new Error('Mistral no devolvió contenido');
const data = typeof content === 'string' ? JSON.parse(content) : content;
data.favicon = $('Extraer texto y favicon').first().json.favicon;
data.areas = (data.areas || []).sort((a, b) => b.score - a.score);
return [{ json: data }];
